# SERVICE PAGES

def service_page(slug,title,lead,img,sections,checks,faqs):
    body=hero(title,'Usluga',lead)+f'''<section class="section"><div class="container split service-lead"><div class="story-img"><img src="{img}" alt="{html.escape(title)}"></div><div><div class="eyebrow">Kristall Diamant</div><h2>Što možete očekivati?</h2>{sections[0]}</div></div></section><section class="section section-soft"><div class="container"><div class="section-head"><div class="eyebrow">Opseg usluge</div><h2>Dogovaramo što stvarno treba vašem prostoru.</h2></div><ul class="checklist">{''.join(f'<li>{x}</li>' for x in checks)}</ul></div></section>'''
    for heading,txt in sections[1:]:
        body+=f'<section class="section"><div class="narrow prose"><h2>{heading}</h2>{txt}</div></section>'
    body+=f'<section class="section section-soft"><div class="container"><div class="section-head"><div class="eyebrow">Česta pitanja</div><h2>Prije nego što rezervirate.</h2></div>{faq(faqs)}</div></section>{cta()}'
    write(Path(f'usluge/{slug}/index.html'),page(f'{title} | Kristall Diamant',lead,f'/usluge/{slug}/','services',body))

